
INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     96, 100, '환상의 짝꿍, 레전드 커플 💖',
    '축하드립니다! 두 분의 티키타카 케미 지수는 레전드 케미 (96–100%)
함께 있는 모든 순간이 즐겁고 편안한, 말 그대로 ''환상의 짝꿍''이시군요. 마치 오랜 시간 호흡을 맞춰온 듀엣처럼, 눈빛만 봐도 서로의 마음을 척척 알아채고, 굳이 애쓰지 않아도 대화가 끊이지 않는 모습입니다. 함께 있으면 웃음이 마를 날이 없고, 힘든 일이 있어도 "우리 사이에 이 정도쯤이야!"라며 유쾌하게 함께 이겨내는 강력한 팀워크를 자랑합니다. 주변 사람들이 "너희 정말 잘 만났다"라며 부러워하는, 모두가 인정하는 ''레전드 커플''이라고 할 수 있겠네요!', '두 분의 티키타카 케미가 폭발하는 이유는, 각자도 매력적인 사람이지만 함께일 때 그 매력이 두 배, 세 배가 되기 때문입니다. 안정적인 마음을 가진 두 분이 만나, 서로의 좋은 점을 끊임없이 발견하고 칭찬해주는 긍정적인 에너지가 넘쳐흐릅니다. 한 분이 툭 던진 농담에 다른 한 분이 빵 터지고, 또 재치있게 받아치는 환상의 호흡을 보여주네요. 갈등이 생겨도 "네가 맞네, 내가 맞네" 싸우기보다 "어떻게 하면 더 재밌게 해결할 수 있을까?"를 함께 고민하는 유연함을 가지고 있습니다. 그래서 두 분의 관계는 시간이 갈수록 더욱 단단해지고, 예측 불가능한 즐거움으로 가득 차게 됩니다. 함께라면 그 어떤 지루한 일상도 신나는 모험으로 바꿀 수 있는 특별한 능력을 가지셨어요.', '이미 두 분은 최고의 케미를 자랑하고 있지만, 이 즐거움을 오랫동안 유지하기 위한 몇 가지 꿀팁을 드릴게요. 첫째, ''고마워''와 ''최고야''라는 말을 아끼지 마세요.지금의 환상적인 호흡을 당연하게 생각하지 않고, "너랑 있으면 정말 재밌어!" 와 같이 서로의 즐거움을 자주 표현해주면 행복이 두 배가 될 거예요. 둘째, 두 분의 ''꿀잼력''을 활용해 새로운 ''우리만의 프로젝트''를 시작해보세요.함께 유튜브 채널을 만들어보거나, 커플 댄스를 배우는 등 두 분의 유쾌함을 세상에 보여줄 수 있는 활동은 어떨까요? 두 분의 사랑스러운 케미는 앞으로도 계속해서 두 분의 삶을 반짝반짝 빛나게 만들어 줄 거예요!', 1
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     92, 96, '알콩달콩, 우린 제법 잘 어울려요 😉',
    '두 분의 티키타카 케미 지수는 높은 시너지 (92–95%)! 서로에게 편안하고 기분 좋은 에너지를 주는, 아주 알콩달콩하고 사랑스러운 커플입니다. 매일이 축제처럼 떠들썩하진 않아도, 함께 있으면 잔잔한 미소가 지어지고 마음이 따뜻해지는 안정감을 느끼고 계시는군요. 주변에서도 "참 잘 어울리는 한 쌍이다"라는 말을 자주 들으실 것 같아요. 가끔 사소한 일로 티격태격하기도 하지만, 그 모습마저도 귀여운 사랑싸움으로 보이는, 기본적으로 서로에 대한 깊은 신뢰와 애정이 깔려있는 건강한 관계입니다.', '두 분의 ''알콩달콩'' 케미는 서로를 존중하는 따뜻한 마음에서 비롯됩니다. 각자 안정적인 마음의 바탕 위에서, 서로의 다름을 틀린 것이 아니라 ''다른'' 것으로 자연스럽게 받아들이고 계세요. 다만 아주 가끔, 서로 피곤하거나 예민한 날에는 평소라면 그냥 넘어갔을 사소한 말투나 행동에 마음이 살짝 엇갈릴 때가 있는 것 같아요. "왜 저렇게 말하지?"라며 서운한 마음이 들 때도 있지만, 다행히 두 분의 관계는 기본적으로 튼튼해서 금방 "에이, 그럴 수도 있지" 하고 쿨하게 넘어가는 지혜를 가지고 있습니다. 이 작은 엇갈림이 두 분의 관계를 더 깊이 이해하게 만드는 건강한 조미료 역할을 하고 있네요.', '두 분의 사랑스러운 관계가 더욱 예쁘게 무르익을 수 있도록 작은 꿀팁을 드릴게요. 첫째, 가끔씩 찾아오는 ''서운함 예보''를 미리 알려주세요."나 오늘 조금 피곤해서 예민보스일 수 있어, 미리 미안!" 과 같이 자신의 상태를 귀엽게 알려주면, 상대방도 오해 없이 더 따뜻하게 배려해 줄 수 있을 거예요. 둘째, 두 분의 ''꽁냥꽁냥''한 순간들을 사진이나 짧은 영상으로 기록해보세요.함께 맛있는 음식을 먹거나, 예쁜 풍경을 볼 때의 행복한 모습을 담아두는 거죠. 나중에 함께 보면서 "우리 이때 정말 즐거웠는데!" 하고 추억을 곱씹는 시간은, 사소한 엇갈림이 찾아왔을 때 관계를 지켜주는 든든한 힘이 되어줄 것입니다.', 2
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     88, 92, '우리는 ''애증''의 베스트 프렌드 🤪',
    '두 분의 티키타카 케미 지수는조화로운 관계 (88–91%)! 두 분은 서로를 너무나 잘 알기에 가장 재미있는 친구가 되기도 하고, 또 너무 잘 알기에 가장 얄미운 라이벌이 되기도 하는, 한마디로 ''애증의 베스트 프렌드'' 같은 커플이네요. 각자 매력 넘치고 괜찮은 사람들이지만, 함께 있을 때면 유독 장난기가 발동해서 서로를 놀리거나 경쟁심이 불타오를 때가 있는 것 같습니다. 그래서 어떤 날은 세상에서 가장 웃긴 콤비였다가, 어떤 날은 "너 정말 이럴 거야?"라며 으르렁거리는, 아주 다이나믹하고 예측 불가능한 재미가 있는 관계입니다.', '두 분의 ''애증 케미''는 각자의 개성과 매력이 뚜렷하기 때문에 나타나는 현상입니다. 두 분 모두 각자의 생각이나 스타일이 확고해서, 서로에게 쉽게 맞춰주기보다 "내 방식이 더 재밌는데?"라며 팽팽하게 맞서는 경우가 종종 있습니다. 특히 한 분이 애정을 표현하며 다가가고 싶을 때, 다른 한 분은 장난을 치거나 딴청을 피우는 식으로 그 마음을 엇갈리게 만들 수 있어요. 사랑하지 않아서가 아니라, 애정을 표현하는 방식이 달라서 생기는 유쾌한 오해인 거죠. 이런 티격태격하는 과정이 두 분의 관계를 지루할 틈 없이 만들지만, 가끔은 너무 심한 장난에 한쪽이 진심으로 마음 상하는 ''경계''를 넘나들 때도 있어 보입니다.', '두 분의 유쾌한 ''애증'' 관계가 상처 대신 즐거움만 남기기 위한 꿀팁을 드릴게요. 첫째, 두 분만의 ''휴전'' 신호를 만들어보세요.장난을 치다가도 한쪽이 "잠깐, 이건 진심으로 서운해"라는 신호를 보내면, 일단 장난을 멈추고 상대방의 마음에 귀 기울여주기로 약속하는 거죠. 둘째, ''놀리는 시간''과 ''칭찬하는 시간''의 균형을 맞춰보세요.하루에 한 번 서로를 신나게 놀렸다면, 잠들기 전에는 "그래도 오늘 네가 한 것 중에 이건 정말 멋있었어"라고 진심 어린 칭찬을 건네는 겁니다. 얄미움과 사랑스러움의 아슬아슬한 줄타기를 즐기면서도, 서로의 마음을 지켜주는 센스를 발휘한다면 두 분은 세상에서 가장 유쾌한 커플이 될 수 있을 거예요.', 3
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     84, 88, '서로 다른 별에서 온 우리 👽',
    '두 분의 티키타카 케미 지수는 안정적 호흡 (84–87%). 두 분은 각자 자신의 별에서는 아주 멋지고 빛나는 존재들이지만, 막상 서로의 궤도에서 만나니 언어나 문화가 달라 조금씩 삐걱거리는 느낌을 받고 있는 ''우주인 커플'' 같아요. 서로를 사랑하고 잘해주고 싶은 마음은 분명하지만, "왜 내 마음을 몰라주지?", "도대체 저 행동은 무슨 의미야?"라며 서로를 이해하기 위해 많은 에너지를 쓰고 있는 모습입니다. 각자의 매력과 능력 덕분에 관계가 유지되고는 있지만, 이 ''다름''에서 오는 피로감이 조금씩 쌓여 "우리는 정말 안 맞는 걸까?" 하는 고민에 빠져있을지도 모릅니다.', '두 분의 ''우주인 케미''는 각자가 가진 고유한 성향이나 가치관이 꽤 다르기 때문에 발생합니다. 예를 들어, 한 분은 갈등이 생기면 바로바로 대화로 풀어야 하는 ''직진 소통 별''에서 왔고, 다른 한 분은 혼자만의 동굴에서 충분히 생각할 시간이 필요한 ''차분한 사색 별''에서 왔을 수 있습니다. 각자의 별에서는 그것이 가장 현명한 방식이었지만, 두 분이 만나니 한쪽은 계속 문을 두드리고 다른 쪽은 계속 문을 닫는 상황이 반복되는 거죠. 이처럼 근본적인 차이가 있다 보니, 아무리 노력해도 서로에게 닿지 않는 것 같은 깊은 무력감을 느끼기 쉽습니다. 서로의 언어를 배우려는 노력이 부족해지면, 이 관계는 금방 지칠 수 있습니다.', '서로 다른 별에서 온 두 분이 행복한 ''우주 정거장''을 만들기 위한 꿀팁입니다. 첫째, 서로의 언어를 배우는 ''외계어 번역기''를 만들어보세요."당신이 침묵하는 건 나를 무시하는 게 아니라, ''생각할 시간이 필요해''라는 뜻이구나" 와 같이, 상대방의 행동에 숨겨진 진짜 의미를 함께 이야기하며 오해를 줄여나가는 겁니다. 둘째, 모든 것을 똑같이 맞추려 하기보다, 각자의 ''개인 영역''을 존중해주세요.모든 것을 함께하는 것만이 사랑은 아닙니다. 서로의 다른 점을 신기한 외계 문화를 탐사하듯 즐기고 존중해줄 때, 두 분은 오히려 더 편안하고 깊은 관계가 될 수 있습니다. "너는 그렇구나, 나는 이런데, 참 신기하다!"라며 서로의 다름을 즐길 수 있게 된다면, 두 분만의 새로운 우주를 만들어갈 수 있을 거예요.', 4
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     80, 84, '아슬아슬 줄타기, 스릴 넘치는 우리 🎢',
    '두 분의 티키타카 케미 지수는균형감 있는 관계 (80–83%)
두 분의 관계는 마치 짜릿한 롤러코스터처럼, 격렬한 즐거움과 아찔한 불안함 사이를 오가는 스릴 넘치는 모습입니다. 서로에게 강렬하게 끌리는 만큼, 부딪힐 때도 아주 강하게 부딪히는 ''자석 커플'' 같아요. 좋을 때는 세상에 둘도 없는 천생연분처럼 느껴지지만, 한번 싸우기 시작하면 "어떻게 나한테 이럴 수 있어?"라며 서로에게 깊은 상처를 주기도 합니다. 각자는 정말 매력적인 사람이지만, 두 사람의 만남이 만들어내는 화학 반응이 너무나 강렬해서 때로는 통제가 어려울 정도입니다. 이 아슬아슬한 관계가 짜릿한 매력으로 느껴질 수도 있지만, 동시에 감정적인 소모가 매우 클 수 있습니다.', '두 분의 ''롤러코스터 케미''는 각자는 괜찮은 사람이지만, 두 분의 조합이 매우 폭발적인 화학 반응을 일으키기 때문에 나타납니다. "나는 너를 이만큼 사랑하는데, 너는 왜 나를 힘들게만 해?" 라는 생각에 빠지기 쉽지만, 사실은 두 분의 성향이 서로의 가장 예민한 부분을 건드리는 방식으로 맞물려 있을 가능성이 높습니다. 각자의 장점 덕분에 어떻게든 관계를 이어가고는 있지만, 이 강렬한 상호작용은 두 분의 마음 에너지를 빠르게 고갈시킬 수 있습니다. 특히 "이 사람 아니면 안 될 것 같아"라는 강한 끌림이, 오히려 이 고통스러운 관계를 놓지 못하게 만드는 ''덫''이 될 수도 있다는 점을 알아차리는 것이 중요합니다.', '짜릿한 롤러코스터를 안전하게 즐기기 위해서는 ''안전벨트''가 필수입니다. 두 분의 관계를 위한 안전벨트를 함께 만들어보세요. 첫째, 감정이 격해질 때는 무조건 ''일시 정지''를 외치는 규칙을 만들어보세요.롤러코스터가 너무 위험한 구간으로 진입하기 전에 잠시 멈추고 숨을 고르는 시간이 필요합니다. "지금은 너무 화가 나서 말이 예쁘게 안 나올 것 같아. 1시간 뒤에 다시 이야기하자" 라고 말하는 용기가 필요합니다. 둘째, 이 관계가 나 자신에게 어떤 영향을 주는지 솔직하게 돌아보는 시간을 가져보세요.이 짜릿함이 나를 살아있게 하는 즐거움인지, 아니면 나를 병들게 하는 고통인지 냉정하게 생각해보아야 합니다. 때로는 가장 사랑하는 사람을 위해, 잠시 롤러코스터에서 내려 각자의 평지를 걷는 시간이 필요할 수도 있습니다.', 5
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     8, 12, '환상의 팀워크, 우린 제법 강력해! 💪',
    '두 분의 티키타카 케미 지수는 든든한 파트너십 (76–79%) 함께 있을 때 서로에게 엄청난 힘이 되어주는, 그야말로 ''환상의 팀워크''를 자랑하는 커플이시네요. 각자 조금씩 약한 부분이 있을지라도, 두 분이 힘을 합치면 그 어떤 어려움도 함께 헤쳐나갈 수 있는 강력한 시너지가 뿜어져 나옵니다. 문제가 생기면 혼자 고민하기보다 "자기야, 우리 이거 어떻게 할까?"라며 자연스럽게 머리를 맞대는, 세상에서 가장 든든한 동료이자 친구 같은 모습입니다. 두 분의 건강하고 건설적인 소통 방식은 이 관계를 계속해서 성장시키는 최고의 무기랍니다!', '두 분의 강력한 팀워크는 서로의 다름을 존중하고 약점을 보완해주는 멋진 궁합에서 비롯됩니다. 각자 마음속에 약간의 걱정거리나 과거의 상처를 가지고 있을 수 있지만 , 두 분의 관계는 그런 약점들을 오히려 따뜻하게 보듬어주는 ''안전지대'' 역할을 톡톡히 하고 있네요 예를 들어, 한 분이 자신감이 부족한 모습을 보일 때, 다른 한 분은 핀잔을 주기보다 "넌 충분히 잘하고 있어!"라며 진심으로 응원해주는 식이죠4 이처럼 서로의 불안정한 부분을 자극하는 대신, 오히려 안정시켜주는 긍정적인 에너지가 계속해서 만들어지고 있습니다. 두 분은 함께일 때, 혼자일 때보다 훨씬 더 강하고 용감한 사람이 되는 것 같아요.', '두 분의 멋진 팀워크를 평생 이어갈 수 있는 몇 가지 꿀팁을 드릴게요. 첫째, 서로의 약한 모습을 보여주는 것을 두려워하지 마세요."사실 나, 이럴 때 조금 불안해져"라고 솔직하게 말했을 때, 상대방이 따뜻하게 안아줄 것이라는 믿음을 계속해서 키워나가세요5. 이 믿음이 깊어질수록 두 분은 세상에 둘도 없는 끈끈한 사이가 될 거예요 둘째, 서로에게 최고의 ''치어리더''가 되어주세요!상대방이 노력하는 모습을 발견할 때마다 "역시 우리 자기가 최고야!"라고 구체적으로 칭찬하고 격려해주세요. 이런 응원들이 모여 각자의 자신감을 키우고, 관계에 대한 만족감도 쑥쑥 자라나게 할 것입니다.', 6
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     76, 80, '쏘쏘한 하루, 보통의 우리 ☕',
    '두 분의 티키타카 케미 지수는 평온한 관계 (72–75%) 우리 주변에서 가장 흔하게 볼 수 있는, 소소한 행복과 가끔의 다툼이 공존하는 ''보통의 연인'' 관계입니다. 서로를 아끼는 마음은 분명하지만, 각자가 가진 작은 고민거리와 두 사람 사이의 사소한 엇갈림이 맞물리면서 관계가 조금은 밋밋하거나 정체된 것처럼 느껴질 때가 있을 거예요 큰 폭풍우는 없지만, 그렇다고 매일 햇살이 쨍쨍한 것도 아닌, 잔잔한 파도가 계속되는 바다와 같은 모습이죠. "우리 사이, 나쁘진 않은데... 엄청 좋은 건가?" 하는 생각이 가끔씩 들 수 있습니다.', '두 분의 관계가 ''보통''인 이유는, 어느 한쪽의 큰 문제라기보다 두 가지 작은 이슈가 동시에 영향을 주기 때문입니다. 예를 들어, 한 분은 스트레스를 받으면 혼자만의 동굴로 들어가는 성향이 있는데, 다른 한 분은 그럴 때 살짝 서운함을 느끼는 소통 스타일을 가지고 있을 수 있어요. 이 두 가지가 만나면, 한 명은 "왜 좀 내버려 두질 않지?"라고 생각하고, 다른 한 명은 "왜 나를 피하는 거야?"라고 오해하며 불필요한 감정 소모를 겪게 되는 거죠. 이처럼 각자는 사소한 문제지만, 두 개가 합쳐져서 관계의 즐거움을 조금씩 깎아내리고 있는 상황입니다', '두 분의 ''쏘쏘한'' 하루를 좀 더 ''꿀잼''으로 만들기 위한 미션을 드릴게요! 첫째, 주 1회 ''아무 말 대잔치'' 시간을 가져보세요!"이번 주에 혹시 나 때문에 쬐끔이라도 서운했던 거 있어?"라고 가볍게 물어보며, 마음에 쌓아두었던 아주 사소한 감정들을 유쾌하게 털어내는 거죠. 둘째, 서로의 ''사용 설명서''를 교환해보세요."나는 스트레스 만땅일 때 혼자 맛있는 거 먹으면 풀리는 타입이야. 이건 자기랑 있기 싫다는 뜻이 절대 아니야!" 와 같이, 자신의 충전 방식을 미리 알려주면 상대방의 오해를 막고 센스 있는 배려를 유도할 수 있답니다', 7
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     72, 76, '사랑하는데 왜 아플까? 💔',
    '두 분의 티키타카 케미 지수는 보통의 케미 (68–71%) 각자 따로 보면 괜찮은 사람들이지만, 함께 대화만 시작하면 이상하게 서로의 아픈 곳을 콕콕 찌르는 듯한 미스터리한 관계입니다. 문제의 핵심은 각자가 가진 작은 상처보다, 그 상처에 자꾸만 소금을 뿌리는 듯한 두 분의 대화 방식에 있을 수 있어요. 분명 사랑하는 마음으로 시작한 대화인데, 끝날 때쯤이면 서로에게 상처만 남기는 일이 자꾸 반복되는 거죠. 그래서 평소엔 즐겁다가도, 한번 갈등이 터지면 걷잡을 수 없이 커지는 경험에 "우린 대체 왜 이럴까?"라며 지쳐있을지도 모릅니다.', '두 분의 관계가 미스터리한 이유는, 각자가 가진 작은 약점이나 불안감을 서로의 소통 방식이 크게 부풀리기 때문입니다. 예를 들어, 한 분이 "나 좀 더 사랑해줘"라는 마음으로 관심을 표현했는데, 다른 한 분이 무심코 "또 시작이네"라는 식의 반응을 보여 큰 상처를 주는 식이죠 즉, 각자의 상처 자체보다, 그 상처를 건드리고 헤집는 두 분의 ''엇갈리는 대화법''이 더 큰 문제입니다. 이 때문에 서로를 "나를 가장 잘 아는 만큼, 나를 가장 아프게 하는 사람"으로 느끼며 애증의 감정을 키워갈 수 있습니다.', '두 분의 미스터리한 상처를 치유하기 위한 특급 처방전을 드릴게요. 첫째, ''탐정 놀이''를 시작해보세요!대화의 ''내용''이 아니라 ''패턴''을 추리하는 겁니다. "가만 보니, 내가 조급하게 말하면 자기는 입을 닫아버리는 패턴이 있네!" 와 같이, 우리만의 ''싸움 공식''을 찾아내는 거죠. 둘째, 위험할 땐 무조건 누르는 ''긴급정지 버튼''을 만들어보세요.대화가 너무 격해져서 서로에게 상처를 줄 것 같을 때, 둘만의 신호(예: "잠깐! 타임!")를 외치고 30분간 휴식 시간을 갖는 거예요. 상처에 소금을 뿌리는 대화를 멈추는 것만으로도, 두 분의 관계는 훨씬 평화로워질 수 있답니다.', 8
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     68, 72, '불협화음 콘서트 🎶',
    '두 분의 티키타카 케미 지수는 소소한 엇갈림 (64–67%) 두 분의 관계는 마치 각자 뛰어난 연주자이지만, 서로 다른 악보를 들고 엉뚱한 연주를 하며 불협화음을 내고 있는 모습과 같습니다. 각자의 매력이나 능력은 분명 괜찮은 편이지만, 두 사람이 함께 만들어내는 관계의 하모니가 계속해서 삐걱거리는 거죠 아마 함께 있는 시간이 편안함보다는 왠지 모를 긴장감과 피로감으로 가득할 수 있습니다. 각자가 가진 작은 고민거리들이, 두 사람의 근본적인 ''다름'' 속에서 훨씬 더 크고 심각한 문제처럼 느껴지면서, 관계를 유지하는 것 자체가 버겁게 느껴질 수 있어요.', '두 분의 ''불협화음''은 서로의 근본적인 성향이나 세상을 바라보는 방식이 꽤 강하게 충돌하기 때문에 발생합니다 각자가 가진 약간의 불안감이나 상처는, 이 근본적인 ''다름''을 만났을 때 마치 작은 불씨가 기름을 만난 것처럼 활활 타오르게 되죠 예를 들어, 한 분은 ''함께하는 시간''을 통해 사랑을 느끼는데, 다른 한 분은 ''각자의 독립성 존중''을 더 중요하게 생각한다면, 서로 사랑할수록 서로에게 상처를 주는 아이러니한 상황이 발생합니다. "왜 내 마음을 몰라주지?"를 넘어 "이 사람은 나랑 너무 다른 사람이구나"라는 깊은 좌절감에 빠지기 쉬워요.', '불협화음 콘서트를 멈추고 아름다운 듀엣곡을 연주하기 위한 방법을 알려드릴게요. 첫째, "노력하면 상대방을 바꿀 수 있을 거야"라는 생각을 잠시 내려놓아야 해요.때로는 노력의 문제가 아니라, 바꿀 수 없는 근본적인 ''다름''의 문제일 수 있다는 걸 인정하는 거죠. 둘째, 두 분의 다른 악보를 객관적으로 읽어줄 ''지휘자''(상담사)의 도움을 진지하게 고려해보세요 전문가와 함께 "우리의 다른 점을 조율해서 새로운 곡을 만들 수 있을까?" 아니면 "아름다운 솔로 연주자로 남는 것이 서로를 위한 길일까?"를 함께 고민하며 현명한 선택을 내릴 수 있도록 도움이 필요합니다.', 9
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     64, 68, '아찔한 롤러코스터 🎢',
    '두 분의 티키타카 케미 지수는 조심스러운 신호 (60–63%)두 분의 관계는 짜릿한 행복과 아찔한 절망 사이를 오가는, 격렬하고 중독적인 ''롤러코스터''와 같아요. 각자는 약간의 어려움을 가진 평범한 사람들이지만, 두 사람의 만남은 이상하게도 서로의 가장 깊은 감정을 자극하며 폭발적인 시너지를 만들어냅니다. 그래서 좋을 때는 세상을 다 가진 것처럼 행복하다가도, 한번 부딪히면 세상이 무너지는 듯한 고통을 겪는, 매우 드라마틱한 관계입니다. 주변에서는 두 분을 보며 안타까워하지만, 정작 두 분은 이 격렬한 관계에서 쉽게 벗어나지 못할 수 있습니다.', '두 분의 ''롤러코스터'' 케미는, 각자가 가진 작은 불안감이나 상처가 서로의 특정 행동이나 말에 의해 극단적으로 자극되어 통제 불가능한 갈등으로 폭발하기 때문에 나타납니다. "네가 어떻게 나한테..."라는 사소한 말다툼이, 순식간에 서로의 과거 상처까지 들춰내는 큰 싸움으로 번지는 식이죠 서로에게 가장 편안한 안식처가 되어주기는커녕, 서로의 약점을 누구보다 잘 알고 가장 아프게 찌르는 존재가 되어버렸을 수 있습니다44. 이처럼 격렬한 감정의 오르내림은 강한 유대감처럼 느껴질 수 있지만, 사실은 두 분의 마음 에너지를 빠르게 고갈시키고 일상생활마저 위협하는 위험한 상태일 수 있습니다.', '아찔한 롤러코스터에서 잠시 내려와 숨을 고르는 시간이 시급합니다. 첫째, 이 관계가 주는 고통의 힘이 얼마나 큰지 두 분 모두 솔직하게 인정해야 합니다."사랑하니까 이 정도 아픔은 괜찮아"라는 말로 스스로를 속여서는 안 돼요. 둘째, 롤러코스터가 너무 위험하게 느껴질 때는 잠시 운행을 멈추는 ''안전거리''를 확보하는 것을 고려해보세요.폭풍우가 몰아칠 때는 잠시 항구에 피하는 것이 현명합니다. 각자 자신의 마음을 돌보고, "우리는 왜 함께일 때 이렇게 극단적으로 변할까?"에 대해 전문가와 함께 깊이 탐색하는 시간이 반드시 필요합니다 이 관계를 계속 타는 것이 과연 두 분 모두를 위한 길인지, 근본적인 질문을 던져야 할 때입니다', 10
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     60, 64, '우리는 서로의 구원자! 🦸',
    '두 분의 티키타카 케미 지수는 정체기 진입 (56–59%), 이 점수에는 아주 특별하고 희망적인 이야기가 담겨 있어요. 각자 마음속에 풀지 못한 고민이나 상처를 안고 있을 수 있지만, 두 분의 만남은 놀랍게도 서로의 아픔을 치유하고 이겨낼 힘을 주는 ''구원''과도 같은 역할을 하고 있네요 혼자 있을 때보다 함께 있을 때 더 강해지고 안정되는 ''1+1=3''의 마법을 경험하고 계시는군요 세상살이가 힘들고 지쳐도, 서로의 곁에서만큼은 편안한 안식과 함께 다시 일어설 용기를 얻는, 세상에서 가장 든든한 지원군이 되어주는 관계입니다', '두 분의 ''구원자 케미''는 서로의 약한 부분을 완벽하게 보완해주는 특별한 궁합에서 비롯됩니다. 예를 들어, 한 분이 불안감에 휩싸일 때 다른 한 분은 마법처럼 그 마음을 알아채고 차분하게 다독여주고, 한 분이 지쳐 넘어지려 할 때 다른 한 분은 든든한 팔을 내어주는 식이죠 서로의 아픈 곳을 찌르는 것이 아니라, 가장 필요한 순간에 가장 따뜻한 위로와 지지를 건네는 방법을 본능적으로 알고 있는 것 같아요. 그래서 이 관계는 단순한 연인을 넘어, 각자의 삶의 어려움을 함께 헤쳐나가는 가장 소중한 ''힐링 캠프''가 되어주고 있습니다.', '두 분의 소중한 관계를 더욱 아름답게 가꾸기 위한 몇 가지 꿀팁을 드릴게요. 첫째, 서로가 서로에게 얼마나 큰 힘이 되는지 자주 표현해주세요. "네가 있어서 정말 다행이야", "너랑 얘기하면 마음이 놓여" 같은 말은 상대방에게 큰 감동과 확신을 줄 거예요. 둘째, 두 분의 끈끈한 관계를 바탕으로 각자의 ''레벨업''을 응원해주세요. 한 분이 새로운 도전을 망설일 때, 다른 한 분이 "넌 무조건 잘할 수 있어!"라며 최고의 팬이 되어준다면, 혼자서는 어려웠을 일도 함께라면 거뜬히 해낼 수 있을 겁니다.', 11
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     56, 60, '날씨 좋은 날도, 흐린 날도 있는 우리 🌦️',
    '두 분의 티키타카 케미 지수는 갈등 예보 (52–55%) 그럭저럭 괜찮지만 가끔은 알 수 없는'' 보통의 연인 관계에 해당합니다. 두 분의 관계는 맑은 날과 흐린 날이 반복되는 변덕스러운 날씨 같아요. 좋을 때는 한없이 맑고 상쾌하다가도, 어떤 날은 이유 없이 서로의 마음에 먹구름이 끼고 서운한 비가 내리기도 하죠 관계가 힘든 이유는 어느 한쪽의 큰 문제라기보다, 각자가 가진 작은 고민과 두 사람 사이의 사소한 엇갈림이 동시에 영향을 주기 때문이에요. 그래서 문제가 어디서 시작된 건지 헷갈릴 때가 많아, 서로에게 서운함만 쌓일 수 있습니다.', '두 분의 ''날씨 케미''는 문제의 원인을 딱 꼬집어 말하기 어렵다는 특징이 있어요. 예를 들어, 한 분이 회사일로 스트레스를 받아 예민해져 있을 때(개인적 어려움), 다른 한 분이 평소처럼 장난을 거는(사소한 마찰) 상황이 생길 수 있죠. 평소라면 웃어넘겼을 장난이, 예민한 날에는 "지금 장난이 나와?"라는 서운함으로 이어져 다툼의 불씨가 될 수 있습니다. 이처럼 각자의 컨디션과 두 사람의 소통 방식이 복잡하게 얽혀, 관계에 안개가 낀 것처럼 답답하게 느껴질 때가 많을 거예요', '두 분의 관계에 맑은 날이 더 많아지도록, 관계의 ''일기 예보''를 해보는 건 어떨까요? 첫째, 지금 내 마음의 날씨를 먼저 알려주는 연습을 해보세요."나 오늘 미세먼지 때문에 조금 예민해" 혹은 "나 오늘 기분 최고 맑음!"처럼요. 내 상태를 미리 알려주면 상대방도 오해 없이 센스있게 대처할 수 있겠죠? 둘째, 두 분만의 ''감정 신호등''을 만들어보세요. 마음이 힘들 때는 ''빨간불''을 켜서 "나 지금 감정 충전이 필요해. 30분만 혼자 있을게!"라고 솔직하게 표현하고, 상대방은 그 신호를 존중해주는 거죠.', 12
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     52, 56, '우린 왜 자꾸 엇갈릴까? 💔',
    '두 분의 티키타카 케미 지수는 서운함 누적 (48–51%) 두 분의 관계는 각자 가진 아픈 마음에, 의도치 않게 서로가 오해라는 돌멩이를 던지고 있는 안타까운 모습이에요. 마음속에 어느 정도의 불안감을 가진 두 분의 소통 방식이, 서로를 안심시켜주기보다 오히려 불안감을 더 크게 자극하고 있습니다. 그래서 "왜 내 마음을 몰라주지?"라는 서운함과 "왜 항상 그런 식이야?"라는 비난이 오가며, 서로에게 깊은 외로움을 안겨줄 수 있죠. 사랑해서 함께 있는데, 오히려 함께라서 더 외로워지는 악순환에 빠져있을 수 있습니다.', '두 분의 ''엇갈림 케미''는 관계에 부정적인 피드백 고리가 만들어져 있다는 것을 의미해요. 예를 들어, 한 분이 가진 ''버림받을까 두려운 마음''(개인적 어려움)을, 갈등이 생겼을 때 대화를 피하고 침묵하는 다른 한 분의 행동(''분명한 갈등'' 상호작용)이 자극하는 경우죠. 침묵은 상대방에게 ''역시 나를 떠날 거야''라는 오해를 불러일으키고, 이는 더 큰 불안과 집착으로 이어져 결국 상대방을 더 멀리 도망가게 만드는 악순환이 반복됩니다. 이처럼 관계가 서로의 상처를 치유하는 공간이 아니라, 약점을 공격하고 들추는 전쟁터처럼 느껴질 수 있어요.', '이 힘든 악순환의 고리를 끊어내기 위한 긴급 처방전입니다. 첫째, 이 반복되는 ''패턴''을 두 분의 ''공공의 적''으로 삼으세요! "앗, 우리 또 그 패턴 나왔다!"라고 함께 알아차리는 것만으로도, 서로를 비난하는 대신 문제를 함께 해결할 팀이 될 수 있어요. 둘째, 두 분만의 ''안전 규칙''을 정해보세요. "화가 나도 절대 ''헤어지자''는 말은 하지 않기", "옛날이야기 꺼내지 않기"처럼, 서로의 가장 아픈 곳을 찌르지 않기로 약속하는 거죠. 이 규칙들이 두 분이 감정의 폭풍 속에서 길을 잃지 않도록 지켜주는 든든한 등대가 되어줄 겁니다.', 13
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     48, 52, '아슬아슬 위태로운 외줄타기 🎪',
    '두 분의 티키타카 케미 지수는 감정 소모 증가 (44–47%) 두 분의 관계는 마치 아슬아슬한 외줄 위에서 서로 균형을 잡으려고 애쓰는, 매우 위태로운 모습입니다 각자 서 있기도 힘든(중간 수준의 개인적 어려움) 상황에서, 두 사람이 함께 걷는 길(심각한 부조화)은 끊임없이 흔들리고 있어요. 이 관계는 더 이상 편안한 안식처가 아니라, 많은 정신적 에너지를 요구하는 스트레스의 주된 원인이 되었을 가능성이 높습니다. 함께 있어도 깊은 외로움을 느끼고, 서로의 작은 행동 하나하나에 예민하게 반응하며 감정적으로 지쳐있는 상태일 수 있습니다', '두 분의 ''외줄타기 케미''는 이미 각자 마음의 짐이 어느 정도 있는 두 분이, 최악의 ''상성''을 만나 문제가 걷잡을 수 없이 커진 경우입니다. ''심각한 부조화''는 두 분의 소통 방식이나 가치관에 깊은 골이 패여있다는 뜻이에요 각자가 가진 불안감과 상처는 이 깊은 골을 만났을 때, 서로를 이해하는 다리가 되기보다 공격하는 무기로 사용될 가능성이 높습니다 "너는 원래 그런 사람이잖아"와 같이, 서로를 있는 그대로 이해하기보다 부정적인 틀에 가두고 판단하게 되죠. 이 관계 안에서는 어떤 노력을 해도 소용없는 것 같은 깊은 무력감에 빠지기 쉽습니다', '외줄 위에서 떨어지지 않으려면 숙련된 조력자의 손길이 필요합니다. 첫째, 관계를 ''개선''하려는 노력 이전에, 이 관계가 내 삶에 어떤 영향을 미치고 있는지 솔직하게 점검해보세요. 이 관계 때문에 잠을 설치거나, 웃는 날이 줄어들지는 않았나요? 둘째, 이 어려운 상황을 두 분만의 힘으로 해결하려 하기보다, 전문가의 도움을 받는 것을 강력하게 추천합니다. 상담을 통해 두 분이 왜 이렇게 힘든지, 그리고 이 외줄타기를 계속하는 것이 과연 두 분 모두를 위한 길인지 함께 탐색하고 안전한 선택을 내릴 수 있도록 도움이 필요합니다.', 14
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     44, 48, '서로를 할퀴는 상처 입은 영혼들 🥀',
    '두 분의 티키타카 케미 지수는 거리감 확대 (40–43%)두 분의 관계는 각자 마음속에 상처를 가진 두 사람이 서로를 보듬어주기는커녕, 오히려 서로의 상처를 더욱 깊게 할퀴고 있는 매우 고통스러운 모습입니다. ''파괴적 시너지''라는 최악의 상성을 가지고 있어, 각자가 가진 보통 수준의 어려움을 만나 감당할 수 없는 수준의 거대한 폭풍으로 키워내고 있죠 관계는 아마 예측 불가능한 갈등과 격렬한 감정의 폭발로 가득 차 있을 것이며, 함께 있는 모든 순간이 살얼음판을 걷는 듯한 긴장감의 연속일 수 있습니다. 서로가 서로에게 가장 위험한 존재가 되어버린, 매우 안타깝고 파괴적인 관계입니다.', '두 분의 ''상처 케미''는 마치 불과 기름의 만남처럼, 각자가 가진 작은 불안의 불씨를 거대한 화재로 순식간에 키워버리는 조합이라는 의미입니다. 각자가 가진 ''중간'' 수준의 개인적 어려움은 이 파괴적인 상호작용의 ''땔감'' 역할을 하게 되죠. "네가 나를 무시해서 내가 이렇게 힘든 거야"와 같이, 모든 문제의 원인을 상대방에게 돌리며 격렬하게 비난하는 패턴이 반복될 수 있습니다 이 관계 안에서 두 분은 서로의 가장 약한 부분을 누구보다 잘 알게 되고, 역설적으로 그 부분을 가장 아프게 공격하는 무기로 사용하게 됩니다.', '지금은 관계의 ''개선''을 논하기 전에, 더 이상의 상처를 막고 각자의 안전을 확보하는 것이 가장 시급합니다 첫째, 두 분의 만남이 서로에게 얼마나 큰 고통을 주고 있는지, 그 파괴적인 힘을 냉정하게 인정해야 합니다. 사랑이라는 이름으로 이 모든 고통을 정당화해서는 안 돼요. 둘째, 이 파괴적인 순환을 멈추기 위해, 일시적인 ''물리적 거리두기''나 ''분리''를 심각하게 고려해야 합니다. 함께 있는 것만으로도 서로를 파괴한다면, 잠시 떨어져 각자의 상처를 돌보는 것이 서로를 위한 최소한의 배려일 수 있습니다. 각자 전문가의 도움을 받으며 자신의 마음을 먼저 돌본 후에야, 이 관계를 어떻게 할 것인지에 대한 건강한 논의를 시작할 수 있을 겁니다.', 15
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     40, 44, '폭풍 속의 등대 💡',
    '두 분의 티키타카 케미 지수는 관계 위태 (36–39%)점수 자체는 낮지만, 그 내용은 기적처럼 아름답고 희망적인 관계일 수 있어요. 두 분은 각자 삶의 거친 폭풍우 속에서 힘겨운 시간을 보내고 있을지 모릅니다. 하지만 놀랍게도, 두 분의 만남은 이 험난한 바다 위에서 서로를 굳건히 지켜주는 ''등대''와 같은 역할을 하고 있네요. 세상 누구보다 서로의 아픔을 잘 이해하고, 가장 따뜻한 위로를 건네는 최고의 동반자입니다. 바깥 세상은 힘들지만, 함께하는 시간만큼은 서로에게 유일한 안식처이자 구원이 되어주는 아주 특별하고 소중한 관계예요.', '두 분의 ''등대 케미''는 서로의 가장 깊은 상처를 알아보고 보듬어주는 특별한 궁합에서 비롯됩니다. 아마 두 분은 비슷한 아픔을 겪었거나, 서로의 마음을 채워줄 수 있는 특별한 연결고리를 가지고 있을 거예요. 그래서 한 분이 과거의 상처로 무너져 내릴 때, 다른 한 분은 누구보다 그 마음을 잘 알기에 따뜻하게 손을 잡아줄 수 있습니다. 하지만 이 관계는 각자가 짊어진 삶의 무게가 너무 무겁기 때문에, 서로에게 기대는 과정에서 함께 지치거나 위태로워질 수 있다는 점을 기억해야 해요. 관계 자체는 건강하지만, 그 관계를 이루는 두 분이 조금 힘겨운 상황인 거죠.', '두 분의 소중한 관계라는 등대의 불빛을 오랫동안 지켜나가기 위한 조언을 드릴게요. 첫째, 서로가 서로의 ''유일한'' 구원자가 되어서는 안 돼요.서로에게 의지하는 것은 아름답지만, 모든 짐을 관계 안에서만 해결하려 하면 관계가 너무 무거워져 무너질 수 있답니다. 둘째, 두 분의 튼튼한 관계를 ''안전 기지'' 삼아, 각자의 마음속 폭풍우를 잠재우기 위한 ''개인 정비'' 시간을 가져보세요.전문가의 상담을 받거나, 각자의 스트레스를 풀 수 있는 건강한 방법을 찾는 것이 필요해요. 각자가 조금씩 더 단단해질 때, 두 분의 등대는 더욱 멀리, 더욱 밝게 빛날 수 있을 거예요.', 16
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     4, 8, '위태로운 조각배 두 척 🚣',
    '두 분의 티키타카 케미 지수는 심리적 소진 (32–35%) 두 분의 관계는 마치 각자도 위태로운 작은 조각배 두 척이, 폭풍우 치는 바다 위에서 서로에게 의지하려 애쓰는 모습 같아요. 두 분 모두 각자의 삶의 무게로 인해 마음의 여유가 없는 상태인데, 이런 상황에서 두 분의 소통 방식마저 삐걱거리다 보니 관계가 더욱 힘들게 느껴질 수 있습니다. 작은 오해나 서운함도 평소보다 훨씬 더 크게 다가오고, 서로에게 위로를 건넬 힘조차 부족할 수 있어요. "나도 이렇게 힘든데, 너는 왜 내 마음을 몰라주니?"라는 섭섭한 마음이 들기 쉬운, 관계가 또 하나의 무거운 짐처럼 느껴질 수 있는 상황입니다.', '두 분의 ''조각배 케미''는 각자 감당해야 할 짐이 너무 많은데, 설상가상으로 관계의 소소한 문제들까지 더해져 어려움이 두 배가 되는 상황이에요. 이는 마치 각자 무거운 짐을 지고 힘겹게 산을 오르는데, 신고 있는 신발마저 불편한 것과 같죠. 각자의 힘든 사정 때문에 두 분은 이미 감정적으로 예민하고 날카로워져 있을 가능성이 높아요. 이런 상황에서 사소한 소통의 엇갈림은, 평소라면 그냥 넘어갈 수 있는 문제도 "역시 나랑은 안 맞아"라는 큰 상처로 이어지게 만들죠. 개인의 문제와 관계의 문제가 서로에게 나쁜 영향을 주며, 두 분의 에너지를 계속해서 고갈시키고 있어요.', '두 분의 조각배가 가라앉지 않도록, 긴급 생존 키트를 드릴게요! 첫째, ''우리''의 문제를 잠시 내려놓고, ''나''의 마음을 먼저 돌보는 ''셀프 케어'' 시간을 가지세요.각자 충분히 잠을 자고, 맛있는 음식을 먹고, 좋아하는 활동을 하며 고갈된 마음의 에너지를 충전하는 것이 최우선이에요. 둘째, 소통할 때는 ''비난'' 대신 ''요청''의 언어를 써보세요."당신은 왜 항상 그래?" 대신 "내가 지금 너무 힘드니, 잠시만 조용히 안아줄 수 있을까?"와 같이, 내 상태를 솔직하게 설명하고 원하는 것을 구체적으로 부탁하는 연습이 필요해요. 불편한 신발을 편한 신발로 갈아 신어야, 험난한 산을 함께 오를 수 있으니까요.', 17
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     36, 40, '상처 입은 채 서로를 밀어내는 사이 🌵',
    '두 분의 티키타카 케미 지수는 불안정 상태 (28–31%) 두 분의 관계는 마음의 상처가 깊은 두 사람이 서로에게 다가가 위로받고 싶어 하면서도, 동시에 가시를 세워 서로를 아프게 밀어내고 있는 매우 고통스러운 상황 같아요. 두 분은 각자 상당한 수준의 개인적인 어려움을 안고 있으며, 두 분의 상호작용 방식은 이 어려움을 보듬어주기는커녕 오히려 더 깊은 상처를 내는 방향으로 작동하고 있습니다. 그래서 사랑하기 때문에 더 깊이 상처받고, 가까워질수록 더 외로워지는 역설적인 관계에 갇혀 있을 가능성이 높습니다.', '두 분의 ''고슴도치 케미''는 각자의 내적인 문제로 인해 감정적으로 매우 취약한 상태에서, 서로의 가장 약한 부분을 정확히 공격하는 상호작용이 더해져 만들어집니다. 한 분이 불안한 마음에 "나 아직 사랑해?"라고 확인받고 싶어 할 때, 다른 한 분은 그 질문의 무게를 견디지 못하고 침묵하거나 회피해버리는 식이죠. 이러한 반응은 상대방에게는 ''거절''로 느껴져 더 큰 불안과 상처를 남기고, 결국 관계는 서로의 존재 자체가 고통이 되는 악순환의 늪에 깊이 빠지게 됩니다.', '이 고통스러운 악순환을 멈추는 것이 무엇보다 시급한 최우선 과제입니다. 첫째, "우리가 서로를 사랑하지만, 지금 우리의 사랑 방식은 서로를 병들게 하고 있어"라고 솔직하게 마주하는 용기가 필요합니다.둘째, 의식적으로 ''휴전''을 선포하세요!문제가 되는 민감한 주제에 대한 대화를 잠시 멈추고, 더 이상 서로의 상처를 자극하지 않는 최소한의 ''안전거리''를 확보하는 것이 중요해요. 이 상태에서 각자 전문가의 도움을 받아 자신의 마음을 먼저 돌보는 것이 현명한 선택일 수 있습니다. 상처가 아물기 전까지는, 서로를 만지는 것조차 고통일 수 있으니까요.', 18
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     32, 36, '무너져가는 다리 위에서 🌉',
    '두 분의 티키타카 케미 지수는 위기 조짐 단계 (24-27%) 두 분의 관계는 이미 곳곳이 무너져 내리고 있는 다리 위에서, 각자 혼자 서 있기도 힘든 두 사람이 위태롭게 서로를 붙잡고 있는 모습입니다. 두 분은 각자 감당하기 벅찬 마음의 짐을 지고 있으며, 두 사람이 함께 서 있는 관계라는 다리는 근본부터 부실하여 금방이라도 무너질 듯 위태롭습니다. 이 관계는 더 이상 두 분에게 어떤 지지나 위로도 되어주지 못하고, 오히려 삶의 가장 큰 스트레스와 고통의 원천이 되었을 가능성이 매우 높습니다. 희망보다는 절망감이, 애정보다는 원망과 피로감이 더 크게 느껴지는, 매우 힘겹고 위태로운 상태입니다.', '두 분의 관계가 ''위기''인 이유는 명확해요. 첫째, 두 분 모두 이미 정서적으로 너무 지쳐있어서, 관계의 문제를 해결하거나 상대방을 배려할 마음의 에너지가 거의 남아있지 않아요. 둘째, 설상가상으로 두 분의 소통 방식이나 가치관이 너무나 근본적으로 달라, 함께 문제를 해결하려고 시도할수록 오히려 상황이 악화되는 최악의 상황입니다. 어떤 노력을 해도 서로에게는 오해와 상처로 돌아올 뿐이죠. 관계는 이미 긍정적인 기능을 거의 잃었으며, 서로의 존재가 각자의 삶을 더욱 힘들게 만드는 짐이 되어버렸을 가능성이 높습니다.', '지금은 무너지는 다리를 ''고치려고'' 애쓰기보다, 우선 각자의 안전부터 확보하는 것이 가장 중요합니다. 첫째, 이 관계가 서로에게 더 이상 안전한 공간이 아니라는 위험성을 심각하게 인지해야 합니다.계속해서 서로에게 상처를 주는 것은 사랑이 아닐 수 있어요. 둘째, 각자의 삶을 지키기 위한 ''비상 조치''가 필요합니다.신뢰할 수 있는 친구나 가족, 혹은 전문가에게 현재의 어려움을 털어놓고 도움을 요청하세요. 일시적으로 거리를 두는 것도 서로를 보호하기 위한 지혜로운 선택일 수 있습니다. 이 다리를 계속 건너는 것이 맞는지, 전문가의 도움을 받아 냉정하고 안전하게 판단해야 합니다.', 19
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     28, 32, '서로를 겨누는 완전무장 커플 🛡️',
    '두 분의 티키타카 케미 지수는 위기 예상단계 (20-23%) 이 모델이 보여줄 수 있는 가장 위험하고 파괴적인 관계 상태입니다. 두 분의 관계는 각자 상처 입고 잔뜩 경계하는 두 사람이, 서로를 향해 완전한 무장을 한 채 팽팽하게 대치하고 있는 모습과 같아요. 각자가 가진 내면의 깊은 고통은 상대방을 향한 불신과 공격성으로 나타나고, 두 사람의 만남은 이러한 공격성을 최대로 증폭시켜 서로에게 돌이킬 수 없는 상처를 입히는 결과를 낳습니다. 이 관계는 더 이상 사랑의 공간이 아니라, 서로의 약점을 공격하고 자존감을 파괴하는 전쟁터가 되었을 가능성이 매우 높습니다.', '두 분의 ''전쟁 케미''는 모든 최악의 조건이 결합되었을 때 나타납니다. 두 분 모두 정서적으로 매우 취약해서 작은 자극에도 크게 반응할 준비가 되어 있는데, 두 분의 상호작용 방식이 정확히 서로의 가장 아픈 곳, 가장 예민한 부분을 건드리는 방식으로 이루어지고 있습니다. 이는 단순한 불협화음을 넘어, 서로의 존재 자체가 상대방의 아픈 기억을 깨우고 위협을 느끼게 만드는 수준일 수 있어요. 관계 안에서 긍정적인 감정은 찾아보기 힘들고, 오직 분노, 경멸, 두려움, 절망과 같은 파괴적인 감정들만이 서로를 지배하고 있을 가능성이 높습니다.', '지금은 관계의 ''개선''이나 ''유지''가 아닌, 두 분 각자의 ''생존''과 ''안전''을 최우선 목표로 삼아야 합니다.첫째, 이 관계가 서로에게 얼마나 해로운지, 그 위험성을 즉시 인정하고 더 이상의 피해를 막기 위한 행동에 나서야 합니다.폭풍의 눈 속에 계속 머무르는 것은 현명하지 않아요. 둘째, 즉시 전문가의 개입을 요청하고, 두 분 사이의 물리적, 정서적 거리를 확보하는 것이 시급합니다.이 파괴적인 상호작용을 멈추기 위해서는 외부의 강력한 중재가 반드시 필요해요. 지금은 ''우리''를 생각할 때가 아니라, 망가져가고 있는 ''나''를 먼저 구해야 할 때입니다.', 20
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     24, 28, '세상의 끝에서 서로를 붙잡다 🤝',
    '두 분의 티키타카 케미 지수는 위기 예상 (16-19%). 하지만 이 점수는 두 분의 관계가 나쁘다는 의미가 아니라, 오히려 너무나 애틋하고 소중하다는 것을 보여주는 특별한 신호일 수 있어요. 두 분은 각자 삶의 거친 폭풍우 속에서 힘겨운 시간을 보내고 있을지 모릅니다. 하지만 놀랍게도, 두 분의 만남은 이 험난한 세상 속에서 서로를 굳건히 지켜주는 ''비밀 아지트''와 같은 역할을 하고 있네요. 세상 누구보다 서로의 아픔을 잘 이해하고, 가장 따뜻한 위로를 건네는 최고의 동반자입니다. 바깥세상은 힘들지만, 함께하는 시간만큼은 서로에게 유일한 안식처이자 구원이 되어주는 아주 특별한 관계입니다.', '두 분의 ''비밀 아지트'' 케미는 서로의 가장 깊고 어두운 상처를 누구보다 잘 알아보고, 따뜻하게 보듬어주는 특별한 궁합에서 비롯됩니다. 아마 두 분은 비슷한 아픔을 겪었거나, 서로의 마음을 채워줄 수 있는 깊은 연결고리를 가지고 있을 거예요. 그래서 한 분이 세상의 무게에 무너져 내릴 때, 다른 한 분은 누구보다 그 마음을 잘 알기에 말없이 곁을 지켜줄 수 있습니다. 하지만 이 관계는 각자가 짊어진 삶의 무게가 너무 무겁기 때문에, 서로에게 기대는 과정에서 함께 지치거나 위태로워질 수 있다는 점을 기억해야 해요. 관계 자체는 너무나 소중하지만, 그 관계를 이루는 두 분이 힘겨운 상황인 거죠.', '두 분의 소중한 아지트를 더 단단하게 지키기 위한 조언을 드릴게요. 첫째, 서로가 서로의 ''유일한'' 기둥이 되어서는 안 돼요.서로에게 의지하는 것은 아름답지만, 모든 짐을 이 아지트 안에서만 해결하려 하면 아지트가 무너질 수 있답니다. 둘째, 두 분의 끈끈한 관계를 ''안전 기지'' 삼아, 각자의 마음을 돌보기 위한 ''외부 전문가''의 도움을 꼭 받아보세요.각자가 조금씩 더 단단해질 때, 두 분의 비밀 아지트는 세상에서 가장 안전하고 편안한 집이 되어줄 것입니다.', 21
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     20, 24, '가라앉는 배 위의 사소한 다툼 🌊',
    '두 분의 티키타카 케미 지수는 위기 경고 (12-15%) 두 분의 관계는 이미 물이 차오르고 있는 배 위에서, 서로 노 젓는 방식이 다르다며 사소한 다툼을 벌이고 있는 위급한 모습입니다. 두 분은 각자 감당하기에도 벅찬, 매우 높은 수준의 개인적인 어려움을 겪고 있어요. 이런 상황에서는 서로를 보듬고 힘을 합쳐도 모자랄 판에, 두 분 사이의 작은 소통의 엇갈림마저 서로에게는 큰 상처와 부담으로 다가오고 있습니다. 각자 너무나 힘들고 예민해져 있기 때문에, 평소라면 웃어넘길 수 있는 사소한 말 한마디에도 깊은 절망감을 느끼게 됩니다.', '두 분의 ''위기 케미''는 각자 마음의 에너지가 완전히 고갈된 상태에서, 관계의 작은 마찰마저 남아있는 에너지를 갉아먹고 있는 상황이에요. 즉, 각자 자신의 생존만으로도 벅찬 두 사람이, 관계에서 발생하는 작은 스트레스까지 추가로 감당해야 하는 이중고를 겪고 있는 거죠. 마음의 여유가 전혀 없기 때문에, 상대방의 작은 실수나 무심함도 ''나를 사랑하지 않는 증거''로 확대 해석하기 쉽습니다. 서로에게 좋은 파트너가 되어주고 싶어도, 그럴 힘이 남아있지 않은 상태예요.', '지금 두 분의 배는 가라앉기 직전입니다. 노 젓는 방식을 따지기 전에, 배에 찬 물을 퍼내는 것이 가장 시급해요. 첫째, ''관계''를 개선하려는 모든 노력을 잠시 멈추고, 각자 ''자신''을 살리는 데 모든 에너지를 집중해야 합니다.전문가의 도움을 받든, 잠시 휴식을 갖든, 각자의 생존을 위한 비상 조치를 취하는 것이 최우선이에요. 둘째, 관계에서 발생하는 추가적인 스트레스를 차단해야 합니다."우리가 잠시 이 문제에 대해서는 이야기하지 말자"와 같이, 갈등을 유발하는 주제에 대한 ''대화 휴전''을 선언하는 것이 필요해요.', 22
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     16, 20, '서로의 상처를 헤집는 악순환 🔁',
    '두 분의 티키타카 케미 지수는 위기 경고 (8-11%)두 분의 만남은 안타깝게도 서로의 깊은 상처를 보듬기보다, 오히려 더 아픈 곳을 찌르고 자극하는 고통의 악순환을 만들어내고 있습니다. 각자 매우 큰 내면의 어려움과 약한 부분을 가지고 있는데, 두 분의 상호작용 방식은 정확히 그 약한 부분을 건드려 폭발시키는 방식으로 작동하고 있어요. 이 관계는 더 이상 사랑의 공간이 아니라, 서로의 아픈 기억과 불안을 끊임없이 자극하고 재현하는 고통스러운 장소가 되었을 가능성이 높습니다. 서로를 원망하고 미워하지만, 동시에 너무나 깊이 얽혀있어 벗어나지도 못하는 덫과 같은 관계일 수 있습니다.', '두 분의 ''악순환 케미''는 각자가 가진 깊은 상처와 불안이, 상대방의 특정 행동에 의해 생존의 위협처럼 느껴질 만큼 강력하게 자극되기 때문에 발생합니다. 이 자극은 과도한 방어기제나 공격적인 행동으로 이어지고, 이는 다시 상대방의 상처를 자극하는 연쇄 반응을 일으키죠. 즉, 두 분은 서로의 존재 자체가 서로의 가장 아픈 상처를 헤집는 ''방아쇠'' 역할을 하고 있는 것입니다. 이 관계 안에서 두 분은 결코 안전함을 느끼지 못하며, 항상 상처받을 준비를 하는 긴장된 상태로 서로를 대하게 됩니다.', '이 고통스러운 악순환의 고리를 끊어내는 것이 무엇보다 시급하며, 이를 위해서는 외부의 개입이 반드시 필요합니다. 첫째, 이 관계가 현재 서로를 치유하는 것이 아니라 파괴하고 있다는 현실을 두 분 모두 인정해야 합니다.사랑이라는 이름으로 이 고통을 더 이상 정당화해서는 안 돼요. 둘째, 이 악순환을 멈추기 위한 ''강제적인 안전장치''가 필요합니다.전문가의 도움을 통해, 두 분이 서로를 자극하지 않는 최소한의 소통 규칙을 정하거나, 일시적으로 거리를 두는 ''치료적 별거''를 고려해보는 것이 현실적인 대안일 수 있습니다.', 23
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     12, 16, '벼랑 끝의 위태로운 동행 🧗',
    '두 분의 티키타카 케미 지수는 위기 발령 (4-7%)두 분의 관계는 각자 벼랑 끝에 서 있기도 힘든 두 사람이, 서로 다른 방향으로 가자고 다투며 위태롭게 손을 잡고 있는 모습입니다. 두 분은 각자 감당하기 힘든 수준의 심리적 어려움을 겪고 있으며, 동시에 두 분의 근본적인 성향과 가치관은 도저히 화합하기 힘든 ''심각한 부조화'' 상태에 있습니다. 이 관계는 두 분에게 그 어떤 위로나 안정감도 주지 못하며, 오히려 각자의 삶을 더욱 혼란스럽고 절망적으로 만드는 가장 큰 원인이 되고 있을 가능성이 높습니다.', '두 분의 ''벼랑 끝 케미''는 개인이 감당해야 할 어려움과 관계 자체가 만들어내는 어려움이 모두 ''최고 위험'' 수준에 근접한, 총체적인 위기 상황을 보여줍니다. 각자 이미 삶의 위기 상황에 처해 있는데, 두 분의 근본적인 ''다름''은 이 위기를 함께 헤쳐나갈 그 어떤 협력도 불가능하게 만들죠. 오히려 서로 다른 생존 방식이 부딪히며, 가라앉는 배 위에서 서로에게서 구명조끼를 빼앗으려는 듯한 파괴적인 다툼으로 이어질 수 있습니다. 이 관계 안에서 ''우리''라는 개념은 사라지고, 오직 고통받는 ''나''와 나를 더 고통스럽게 만드는 ''너''만 존재하게 됩니다.', '지금 이 관계는 두 분의 정신 건강에 심각한 해를 끼칠 수 있는 매우 위험한 상태일 수 있습니다. ''관계를 지켜야 한다''는 생각보다 ''나 자신을 지켜야 한다''는 내면의 목소리에 귀를 기울여야 할 때입니다.첫째, 지금 즉시 각자의 안전과 안녕을 확보할 수 있는 외부 지원 시스템을 찾으세요.신뢰할 수 있는 가족, 친구, 그리고 무엇보다 전문가의 도움이 절실합니다. 둘째, 관계를 ''개선''하려는 시도 자체가 서로에게 더 큰 상처가 될 수 있음을 인지하고, 잠시 모든 노력을 멈추어야 합니다.', 24
);


INSERT INTO report_tikitaka (
    min_index, max_index, title, overall_evaluation,
    detail_evaluations, counseling_text, sequence
) VALUES (
     0, 4, '모든 것을 삼키는 블랙홀 ⚫',
    '두 분의 티키타카 케미 지수는 최악 경고 (0-3%) 이 모델이 측정할 수 있는 가장 파괴적이고 위험한, 최악의 관계 상태입니다. 두 분의 만남은 각자 이미 한계에 다다른 두 사람이, 서로의 존재마저 삼켜버리는 거대한 ''블랙홀''을 만들어낸 것과 같습니다. 이 관계는 단순한 갈등이나 어려움을 넘어, 두 사람의 자존감, 희망, 정신 건강 등 모든 것을 파괴하는 ''재앙'' 수준의 시너지를 만들어내고 있습니다. 관계 안에는 그 어떤 긍정적인 감정도 남아있지 않으며, 오직 깊은 절망과 분노, 두려움만이 가득할 것입니다.', '두 분의 ''블랙홀 케미''는 모든 최악의 조건이 결합된 ''완전한 폭풍(perfect storm)''입니다. 두 분 모두 심리적으로 극도로 취약하고 방어적인 상태인데, 두 분의 만남이 정확히 서로의 가장 깊은 트라우마와 약점을 건드려 폭발시키는, 가장 잔인한 방식으로 이루어지고 있습니다. 서로의 존재 자체가 상대방에게는 가장 큰 위협이자 고통의 원천이 됩니다. 이 관계 안에서 두 분은 서로의 가장 어둡고 아픈 면을 마주하게 될 가능성이 높으며, 이는 돌이킬 수 없는 깊은 상처와 불신을 남길 수 있습니다.', '지금은 관계의 ''개선''이나 ''유지''가 아닌, 두 분 각자의 ''생존''과 ''안전''을 최우선 목표로 삼아야 합니다.첫째, 이 관계가 서로에게 얼마나 해로운지, 그 위험성을 즉시 인정하고 더 이상의 피해를 막기 위한 행동에 나서야 합니다.폭풍의 눈 속에 계속 머무르는 것은 현명하지 않아요. 둘째, 즉시 전문가의 개입을 요청하고, 두 분 사이의 물리적, 정서적 거리를 확보하는 것이 시급합니다.이 파괴적인 상호작용을 멈추기 위해서는 외부의 강력한 중재가 반드시 필요해요. 지금은 ''우리''를 생각할 때가 아니라, 망가져가고 있는 ''나''를 먼저 구해야 할 때입니다.', 25
);
